    private boolean keyboardEnabled(){InputMethodManager manager=(InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);for(android.view.inputmethod.InputMethodInfo method:manager.getEnabledInputMethodList())if(method.getPackageName().equals(getPackageName()))return true;return false;}
