    private TextWatcher watcher(TextChanged action){return new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){action.changed(s.toString());}public void afterTextChanged(Editable e){}};}
